 ,p_stmt_text => 
'create or replace FUNCTION xx_apx_get_current_environment '||wwv_flow.LF||
'RETURN VARCHAR2'||wwv_flow.LF||
'IS'||wwv_flow.LF||
'    v_environment VARCHAR2(200);'||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
'    -- Determinar ambiente basado en diferentes criterios'||wwv_flow.LF||
'    IF UPPER(SYS_CONTEXT(''USERENV'', ''DB_NAME'')) = ''EBSUAT'' THEN '||wwv_flow.LF||
'        v_environment := '''';'||wwv_flow.LF||
'    ELSIF UPPER(SYS_CONTEXT(''USERENV'', ''DB_NAME''))  = ''EBST'' THEN'||wwv_flow.LF||
'        v_environment := ''Ejecutando aplicacion de TEST'';'||wwv_flow.LF||
'    ELS'||
'IF UPPER(SYS_CONTEXT(''USERENV'', ''DB_NAME'')) = ''EBSD'' THEN'||wwv_flow.LF||
'        v_environment := ''Ejecutando aplicacion de DESARROLLO'';'||wwv_flow.LF||
'    ELSIF UPPER(SYS_CONTEXT(''USERENV'', ''DB_NAME'')) = ''EBSTPF'' THEN'||wwv_flow.LF||
'        v_environment := ''Ejecutando aplicacion de TESTFIX'';    '||wwv_flow.LF||
'    ELSE'||wwv_flow.LF||
'        v_environment := ''DESCONOCIDO'';'||wwv_flow.LF||
'    END IF;'||wwv_flow.LF||
'    '||wwv_flow.LF||
'    RETURN v_environment;'||wwv_flow.LF||
'END xx_apx_get_current_environment;'
    ,p_result_size => 0
    ,p_result_rows => 0
    ,p_msg => 'Function created.'
    ,p_success => 'Y'
    ,p_failure => 'N'
